WITH valid AS (SELECT id, customer_id, account_type, opened_date, status, UPPER(account_type) AS account_type_upper, COALESCE(status, 'NONE') AS resolved_status FROM accounts WHERE opened_date >= TO_DATE('2024-04-29') AND customer_id IS NOT NULL) SELECT *, ROW_NUMBER() OVER w_running AS seq_no, ROW_NUMBER() OVER (PARTITION BY status ORDER BY opened_date, id) AS event_seq FROM valid WINDOW w_running AS (PARTITION BY account_type ORDER BY opened_date DESC, id);
